with chosen as(select * from public.works where id=any(array[1356,2650,2981,3335,5042,2654,1414,3465,5873,2980,3383,3387,3413,3175,3456,3418,3449,3554,4928,3420,5000,5010,5033,5888,5954,5964,6052,3171,3417,3562,5056,5785,5857,6022,2323,3197,5860,6082,6118,6138,6168,1629,2334,1585]::bigint[])) select jsonb_build_object('checked_at',clock_timestamp(),'works',(select jsonb_agg(to_jsonb(t) order by id) from chosen t),'authors',(select jsonb_agg(to_jsonb(t) order by id) from public.authors t where id in(select author_id from chosen)),'editions',(select jsonb_agg(to_jsonb(t) order by id) from public.editions t where work_id in(select id from chosen)),'descriptions',(select coalesce(jsonb_agg(to_jsonb(t) order by work_id,language),'[]') from public.catalog_work_descriptions t where work_id in(select id from chosen)),'metadata',(select coalesce(jsonb_agg(to_jsonb(t) order by edition_id),'[]') from public.catalog_edition_metadata t where work_id in(select id from chosen))) as preflight;
